inbound.set-body:
@{
      var body = new Newtonsoft.Json.Linq.JObject();
      body["warehouse_id"] = "{{databricks-warehouse-id}}";
      body["statement"] = "SHOW TABLES IN {{databricks-catalog}}.{{databricks-schema}}";
      body["wait_timeout"] = "50s";
      body["on_wait_timeout"] = "CONTINUE";
      body["format"] = "JSON_ARRAY";
      body["disposition"] = "INLINE";
      return body.ToString();
    }
